function updateSection(){if(!renderer||!state.project)return;capGroup.clear();if(state.walk){renderer.clippingPlanes=[];return;}if(state.floor!=='all'){const f=activeFloor();$('wall-height-value').value=`${round(state.wallHeight,2)} m`;if(!state.walls&&state.volumes){renderer.clippingPlanes=[];return;}sectionPlane.set(new THREE.Vector3(0,-1,0),f.elevation+state.wallHeight);renderer.clippingPlanes=[sectionPlane];return;}if(state.section<=0){renderer.clippingPlanes=[];$('section-value').value='完整';return;}const p=state.project,axis=state.sectionAxis,limit=axis==='x'?p.width:p.depth,cut=limit*(state.section/100*.96+.02),sign=state.reversed?1:-1;sectionPlane.set(new THREE.Vector3(axis==='x'?sign:0,0,axis==='z'?sign:0),-sign*cut);renderer.clippingPlanes=[sectionPlane];$('section-value').value=`${Math.round(cut*10)/10} m`;
  for(const floor of p.floors){for(const wall of floor.walls){if(!state.walls||wall.type==='railing')continue;const c1=axis==='x'?wall.a[0]:wall.a[1],c2=axis==='x'?wall.b[0]:wall.b[1];if((c1-cut)*(c2-cut)>0||Math.abs(c1-c2)<.001)continue;const t=(cut-c1)/(c2-c1),other=axis==='x'?wall.a[1]+(wall.b[1]-wall.a[1])*t:wall.a[0]+(wall.b[0]-wall.a[0])*t;if(axis==='x')addCap(cut,floor.elevation,other,.012,floor.height,wall.thickness);else addCap(other,floor.elevation,cut,wall.thickness,floor.height,.012);}
    const cross=[];for(const polygon of [floor.floorOutline,...floor.voids])polygon.forEach((a,i)=>{const b=polygon[(i+1)%polygon.length],ca=axis==='x'?a[0]:a[1],cb=axis==='x'?b[0]:b[1];if((ca<=cut&&cb>cut)||(cb<=cut&&ca>cut)){const t=(cut-ca)/(cb-ca);cross.push(axis==='x'?a[1]+(b[1]-a[1])*t:a[0]+(b[0]-a[0])*t);}});cross.sort((a,b)=>a-b);for(let i=0;i+1<cross.length;i+=2){const mid=(cross[i]+cross[i+1])/2,len=cross[i+1]-cross[i];if(axis==='x')addCap(cut,floor.elevation-slab,mid,.014,slab,len);else addCap(mid,floor.elevation-slab,cut,len,slab,.014);}}
}
function setFloor(id){state.floor=id;state.room=null;state.selection=null;state.walk=false;document.body.classList.remove('walk-mode');$('walk-panel').hidden=true;document.querySelectorAll('#floor-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.floor===id));const f=activeFloor();$('floor-heading').textContent=id==='all'?'全部空间':f.name;$('floor-subtitle').textContent=id==='all'?`${state.project.floors.length} 层 · ${state.project.floors.reduce((n,f)=>n+f.rooms.length,0)} 个空间`:`${f.rooms.length} 个空间 · 净高 ${round(f.height,1)} m`;$('scene-kicker').textContent=id==='all'?'WHOLE MODEL':`${f.name} · FLOOR VIEW`;$('scene-title').textContent=id==='all'?'模型总览':f.name;$('scene-meta').textContent=id==='all'?'横向与竖向剖面可调节':`室内净高 ${round(f.height,1)} m · 楼板 0.20 m`;state.wallHeight=Math.min(state.wallHeight,f.height);$('wall-height').max=f.height;$('wall-height').value=state.wallHeight;renderRoomList();renderInspector();updateVisibility();updateSection();if(state.view==='top')setView('top');else focusCamera();}
