function renderRoomList(){const root=$('room-list');root.replaceChildren();if(state.floor==='all'){for(const floor of state.project.floors){const b=document.createElement('button');b.textContent=`⌂  ${floor.name} · ${floor.rooms.length} 个空间`;b.onclick=()=>setFloor(floor.id);root.appendChild(b);}return;}activeFloor().rooms.forEach((room,i)=>{const b=document.createElement('button');b.classList.toggle('active',state.room===room.id);const label=document.createElement('span');label.textContent=`◫  ${room.name}`;const index=document.createElement('span');index.className='room-index';index.textContent=String(i+1).padStart(2,'0');b.append(label,index);b.onclick=()=>{state.room=room.id;select({kind:'room',floor:state.floor,id:room.id});renderRoomList();focusCamera();};root.appendChild(b);});}
function select(s){state.selection=s;if(s?.floor&&state.floor!==s.floor)setFloor(s.floor);state.selection=s;const item=selectedRecord();if(s?.kind==='room')state.room=s.id;renderInspector();renderRoomList();if(renderer)buildScene(false);$('scene-title').textContent=item?.name||activeFloor().name;}
