function updateRoomFloorForWall(floor,oldWall,newWall){for(const room of floor.rooms){room.polygon=room.polygon.map(p=>{if(pointDist(p,oldWall.a)<.28)return [...newWall.a];if(pointDist(p,oldWall.b)<.28)return [...newWall.b];return p;});}}

