  if(s.kind==='opening'){const wall=floor.walls.find(w=>w.openings.some(o=>o.id===s.id));if(wall){const at=t=>[wall.a[0]+(wall.b[0]-wall.a[0])*t,wall.a[1]+(wall.b[1]-wall.a[1])*t];handle(...at(item.start),'start');handle(...at(item.end),'end');handle(...at((item.start+item.end)/2),'move');}}
