function undo(){const last=undoStack.pop();if(!last){toast('暂无可撤销操作');return;}state.project=normalizeProject(last);scheduleSave();buildScene(false);renderRoomList();renderInspector();toast('已撤销');}
function removeSelected(){const s=state.selection;if(!s)return;if(s.kind==='room'&&floorOf(s.floor).rooms.length<=1){toast('每层至少保留一个空间');return;}if(s.kind==='wall'){const wall=selectedRecord();if(wall.role==='exterior'){toast('外墙轮廓已锁定，不能删除');return;}if(wall.construction==='filled'){toast('图纸填充实墙需先改为可拆内墙');return;}}mutate(()=>{const floor=floorOf(s.floor);if(s.kind==='room')floor.rooms=floor.rooms.filter(x=>x.id!==s.id);if(s.kind==='wall')floor.walls=floor.walls.filter(x=>x.id!==s.id);if(s.kind==='opening')for(const wall of floor.walls)wall.openings=wall.openings.filter(x=>x.id!==s.id);if(s.kind==='furniture')floor.furniture=floor.furniture.filter(x=>x.id!==s.id);if(s.kind==='surface')floor.surfaces=floor.surfaces.filter(x=>x.id!==s.id);state.selection=null;state.room=null;});toast('已删除');}
function canvasRay(event){const rect=renderer.domElement.getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1),camera);return raycaster;}
