function onPointerUp(){if(!drag)return;undoStack.push(drag.original);if(undoStack.length>30)undoStack.shift();drag=null;controls.enabled=true;state.project=normalizeProject(state.project);scheduleSave();buildScene(false);renderInspector();}

function enterWalk(){if(state.floor==='all'){setFloor(state.project.floors[0].id);}const floor=activeFloor(),room=floor.rooms.find(r=>r.id===state.room)||floor.rooms[0];state.room=room.id;walkSaved={position:camera.position.clone(),target:controls.target.clone(),up:camera.up.clone(),fov:camera.fov,wallHeight:state.wallHeight};state.walk=true;state.eye=Math.min(1.65,floor.height-.2);const center=room.polygon.reduce((v,p)=>[v[0]+p[0],v[1]+p[1]],[0,0]).map(v=>v/room.polygon.length);camera.up.set(0,1,0);camera.position.set(center[0],floor.elevation+state.eye,center[1]);state.yaw=0;state.pitch=0;camera.fov=68;controls.enabled=false;document.body.classList.add('walk-mode');$('walk-panel').hidden=false;$('eye-slider').value=state.eye;updateWalkCamera();updateVisibility();updateSection();toast('已进入漫游：WASD 移动，Esc 退出');}
function exitWalk(){if(!state.walk)return;state.walk=false;controls.enabled=true;document.body.classList.remove('walk-mode');$('walk-panel').hidden=true;if(walkSaved){camera.position.copy(walkSaved.position);controls.target.copy(walkSaved.target);camera.up.copy(walkSaved.up);camera.fov=walkSaved.fov;state.wallHeight=walkSaved.wallHeight;}camera.updateProjectionMatrix();updateVisibility();updateSection();walkSaved=null;}
function updateWalkCamera(){if(!state.walk)return;const floor=activeFloor();camera.position.y=floor.elevation+state.eye;const yaw=state.yaw*Math.PI/180,pitch=state.pitch*Math.PI/180,direction=new THREE.Vector3(Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),Math.cos(yaw)*Math.cos(pitch));controls.target.copy(camera.position).addScaledVector(direction,3);camera.lookAt(controls.target);camera.updateProjectionMatrix();$('eye-value').value=`${round(state.eye)} m`;$('fov-value').value=`${round(camera.fov,0)}°`;$('yaw-value').value=`${round(state.yaw,0)}°`;$('pitch-value').value=`${round(state.pitch,0)}°`;}
function moveWalk(direction){if(!state.walk)return;const yaw=state.yaw*Math.PI/180,forward=[Math.sin(yaw),Math.cos(yaw)],right=[forward[1],-forward[0]];let delta=direction==='forward'?forward:direction==='back'?forward.map(v=>-v):direction==='right'?right:right.map(v=>-v);camera.position.x=clamp(camera.position.x+delta[0]*.3,.15,state.project.width-.15);camera.position.z=clamp(camera.position.z+delta[1]*.3,.15,state.project.depth-.15);updateWalkCamera();}

function openDatabase(){return new Promise((resolve,reject)=>{const request=indexedDB.open('spatial-editor-projects',1);request.onupgradeneeded=()=>request.result.createObjectStore('projects');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function storeProject(project){const database=await openDatabase();await new Promise((resolve,reject)=>{const tx=database.transaction('projects','readwrite');tx.objectStore('projects').put(project,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});database.close();}
async function loadStoredProject(){const database=await openDatabase();const result=await new Promise((resolve,reject)=>{const tx=database.transaction('projects');const request=tx.objectStore('projects').get('current');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});database.close();return result;}
let saveTimer;function scheduleSave(){clearTimeout(saveTimer);$('save-status').textContent='保存中…';saveTimer=setTimeout(async()=>{try{await storeProject(state.project);$('save-status').textContent='已自动保存到本机';}catch(error){$('save-status').textContent='自动保存失败，请导出项目 JSON';toast('本机存储空间不足，请导出项目 JSON');}},500);}
function downloadProject(){const content=JSON.stringify(state.project,null,2),link=document.createElement('a');link.href=URL.createObjectURL(new Blob([content],{type:'application/json'}));link.download=`${state.project.name.replace(/[\\/:*?"<>|]/g,'_')}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
function openProject(raw){try{state.project=normalizeProject(raw);state.floor='all';state.room=null;state.selection=null;state.view='3d';state.walls=true;state.volumes=true;state.surfaces=true;state.furniture=true;state.levelMode='stack';state.spaceOnly=false;previousDisplay=null;syncDisplayControls();undoStack=[];$('editor-title').textContent=state.project.name;$('start-screen').hidden=true;$('editor-screen').hidden=false;if(!renderer)initThree();camera.up.set(0,1,0);document.querySelectorAll('.view-toggle button').forEach(b=>b.classList.toggle('active',b.id==='view-3d'));renderFloorTabs();buildScene();setFloor('all');scheduleSave();toast('空间模型已打开');}catch(error){toast(error.message);throw error;}}
function showPlan(floor){const tabs=$('plan-tabs');tabs.replaceChildren();for(const f of state.project.floors){const b=document.createElement('button');b.textContent=f.name;b.onclick=()=>showPlan(f.id);tabs.appendChild(b);}const selected=floorOf(floor)||state.project.floors[0];$('plan-image').hidden=!selected.sourceImage;$('plan-image').src=selected.sourceImage||'';if(!selected.sourceImage)toast('这个项目没有保存原始图纸');}
async function fileToPlan(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error(`${file.name} 不是支持的图片格式`);if(file.size>8*1024*1024)throw new Error(`${file.name} 超过 8 MB`);const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});const image=new Image();image.src=dataUrl;await image.decode();return {name:file.name,dataUrl,imageWidth:image.naturalWidth,imageHeight:image.naturalHeight};}
function renderPlanPreviews(){const previews=$('plan-previews');previews.replaceChildren();previews.hidden=!files.length;for(const [i,plan] of files.entries()){const figure=document.createElement('figure'),image=document.createElement('img'),caption=document.createElement('figcaption'),remove=document.createElement('button');image.src=plan.dataUrl;image.alt=`第 ${i+1} 层图纸`;caption.textContent=`${i+1}F · ${plan.name}`;remove.type='button';remove.className='remove-plan';remove.textContent='×';remove.title=`删除第 ${i+1} 层图纸`;remove.setAttribute('aria-label',`删除第 ${i+1} 层图纸 ${plan.name}`);remove.onclick=event=>{event.preventDefault();event.stopPropagation();const [deleted]=files.splice(i,1);$('plan-files').value='';renderPlanPreviews();toast(`已删除 ${deleted.name}`);};figure.append(image,caption,remove);previews.appendChild(figure);}}
async function setFiles(fileList){try{files=await Promise.all([...fileList].slice(0,10).map(fileToPlan));renderPlanPreviews();toast(`已导入 ${files.length} 张图纸`);}catch(error){toast(error.message);}}
async function recognize(){if(!files.length){toast('请先上传至少一张平面图');return;}const button=$('generate');button.disabled=true;button.textContent='准备分阶段识别…';try{const width=Number($('plan-width').value)||undefined,depth=Number($('plan-depth').value)||undefined,height=Number($('floor-height').value)||3;const plans=files.map(plan=>({...plan,widthMeters:width,depthMeters:depth,floorHeight:height}));const response=await fetch('./api/recognize',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/x-ndjson'},body:JSON.stringify({name:$('project-name').value,plans,floorHeight:height})});if(!response.ok){const payload=await response.json().catch(()=>({}));throw new Error(payload.error||'当前部署未启用 AI 识别服务，请运行配套 Node 服务或先建空白空间');}if(!response.body)throw new Error('浏览器不支持分阶段识别结果');const reader=response.body.getReader(),decoder=new TextDecoder();let pending='',project=null;const event=line=>{if(!line.trim())return;const payload=JSON.parse(line);if(payload.type==='progress'){button.textContent=`${payload.floor}/${payload.total}层 · ${payload.stage}…`;$('ai-status').textContent=`正在识别：${payload.stage}（第 ${payload.floor}/${payload.total} 层）`;}if(payload.type==='error')throw new Error(payload.error);if(payload.type==='done')project=payload.project;};while(true){const {value,done}=await reader.read();pending+=decoder.decode(value||new Uint8Array(),{stream:!done});let newline;while((newline=pending.indexOf('\n'))>=0){event(pending.slice(0,newline));pending=pending.slice(newline+1);}if(done)break;}if(pending.trim())event(pending);if(!project)throw new Error('识别未返回项目数据');openProject(project);}catch(error){toast(error.message);$('ai-status').textContent=`识别失败：${error.message}`;$('ai-status').classList.add('error');}finally{button.disabled=false;button.innerHTML='识别并生成空间模型 <span>→</span>';}}
function syncDisplayControls(){$('show-walls').checked=state.walls;$('show-volumes').checked=state.volumes;$('show-surfaces').checked=state.surfaces;$('show-furniture').checked=state.furniture;$('only-spaces').classList.toggle('active',state.spaceOnly);$('level-mode').textContent={stack:'楼层叠放',explode:'楼层爆炸',solo:'单层查看'}[state.levelMode];}
function setDisplay(mode,checked){state.spaceOnly=false;previousDisplay=null;state[mode]=checked;syncDisplayControls();buildScene(false);}
function toggleOnlySpaces(){if(!state.spaceOnly){previousDisplay={walls:state.walls,volumes:state.volumes,surfaces:state.surfaces,furniture:state.furniture};state.walls=false;state.volumes=true;state.surfaces=false;state.furniture=false;state.spaceOnly=true;}else{Object.assign(state,previousDisplay||{walls:true,volumes:true,surfaces:true,furniture:true});state.spaceOnly=false;previousDisplay=null;}syncDisplayControls();buildScene(false);}
async function checkAi(){try{const response=await fetch('./api/status');if(!response.ok)throw new Error('AI service unavailable');const status=await response.json();$('ai-status').textContent=status.aiReady?`AI 识别已就绪 · ${status.model}`:'AI 识别未配置。可先建空白空间，或按说明设置 INFERERA_API_KEY。';$('ai-status').classList.toggle('error',!status.aiReady);}catch{$('ai-status').textContent='在线静态版可建空白空间或导入项目；AI 识别需运行配套服务';$('ai-status').classList.add('error');}}
async function showContinue(){try{const previous=await loadStoredProject();if(!previous)return;const button=document.createElement('button');button.textContent=`继续上次项目：${previous.name}`;button.onclick=()=>openProject(previous);document.querySelector('.import-alternatives').appendChild(button);}catch{}}

function addRoom(){if(state.floor==='all')setFloor(state.project.floors[0].id);const floor=activeFloor(),p=state.project,x=clamp(p.width/2,1,p.width-1),z=clamp(p.depth/2,1,p.depth-1),w=Math.min(3,p.width*.35),d=Math.min(3,p.depth*.35),id=uid('room');mutate(()=>{floor.rooms.push({id,name:`未命名${floor.rooms.length+1}`,polygon:[[x-w/2,z-d/2],[x+w/2,z-d/2],[x+w/2,z+d/2],[x-w/2,z+d/2]]});state.selection={kind:'room',floor:floor.id,id};});toast('空间已添加，拖动顶点可调整范围');}
function addWall(){if(state.floor==='all')setFloor(state.project.floors[0].id);const floor=activeFloor(),p=state.project,id=uid('wall');mutate(()=>{floor.walls.push({id,name:'可拆内墙',a:[p.width*.35,p.depth*.5],b:[p.width*.65,p.depth*.5],thickness:.18,type:'wall',role:'interior',construction:'inferred',openings:[]});state.selection={kind:'wall',floor:floor.id,id};});toast('可拆内墙已添加');}
function addFurniture(){if(state.floor==='all')setFloor(state.project.floors[0].id);const floor=activeFloor(),p=state.project,id=uid('furniture');mutate(()=>{floor.furniture.push({id,name:'新家具',type:'chair',x:p.width/2,z:p.depth/2,w:.55,d:.55,h:.9,rotation:0});state.selection={kind:'furniture',floor:floor.id,id};});toast('家具已添加，可在右侧选择类型');}
function addSurface(type){if(state.floor==='all')setFloor(state.project.floors[0].id);const floor=activeFloor(),p=state.project,id=uid('surface'),margin=Math.min(1,Math.min(p.width,p.depth)*.08),polygon=[[margin,margin],[p.width-margin,margin],[p.width-margin,p.depth-margin],[margin,p.depth-margin]],labels={slab:'新楼板',ceiling:'新吊顶',roof:'新屋面',leanTo:'新雨棚'};mutate(()=>{floor.surfaces.push({id,name:labels[type],type,polygon,elevation:type==='slab'?0:floor.height,thickness:.2,pitch:type==='roof'||type==='leanTo'?12:0,drainage:type==='leanTo',material:type==='roof'?'metal':'concrete'});state.selection={kind:'surface',floor:floor.id,id};});toast(`${labels[type]}已添加，可拖动顶点修改轮廓`);}
function addBlock(){if(state.floor==='all')setFloor(state.project.floors[0].id);const floor=activeFloor(),p=state.project,id=uid('furniture');mutate(()=>{floor.furniture.push({id,name:'自定义体块',type:'other',x:p.width/2,z:p.depth/2,w:1.2,d:1.2,h:1.2,rotation:0,material:'custom',customBlock:true,editMode:'object',selectedFace:0,faceMaterials:Array(6).fill('custom')});state.selection={kind:'furniture',floor:floor.id,id};});toast('自定义体块已添加，可切换对象、面、边与环线编辑');}
function toggleLevelMode(){state.levelMode=state.levelMode==='stack'?'explode':state.levelMode==='explode'?'solo':'stack';syncDisplayControls();updateVisibility();focusCamera();toast({stack:'已恢复楼层叠放',explode:'已展开楼层',solo:'当前显示第一层，可用顶部楼层标签切换'}[state.levelMode]);}
function startBlank(){const width=clamp(Number($('plan-width').value)||10,2,100),height=clamp(Number($('floor-height').value)||3,2,8),depth=clamp(Number($('plan-depth').value)||(files[0]?width*files[0].imageHeight/files[0].imageWidth:width*.8),2,100),p=createBlankProject($('project-name').value||'未命名项目',width,depth,height);if(files.length){const first=p.floors[0];first.sourceImage=files[0].dataUrl;for(let i=1;i<files.length;i++){const copy=structuredClone(first);copy.id=`floor-${i+1}`;copy.name=`${i+1}层`;copy.elevation=i*(height+slab);copy.sourceImage=files[i].dataUrl;copy.rooms[0].id=`room-${i+1}`;copy.walls.forEach((wall,wi)=>wall.id=`wall-${i+1}-${wi+1}`);p.floors.push(copy);}}openProject(p);}
function setView(view){state.view=view;document.querySelectorAll('.view-toggle button').forEach(b=>b.classList.toggle('active',b.id===`view-${view}`));if(view==='top'){const p=state.project,target=new THREE.Vector3(p.width/2,state.floor==='all'?p.floors.at(-1).elevation:activeFloor().elevation,p.depth/2);controls.target.copy(target);camera.up.set(0,0,-1);camera.position.set(target.x,target.y+Math.max(p.width,p.depth)*1.6,target.z+.001);camera.lookAt(target);controls.update();}else{camera.up.set(0,1,0);focusCamera();}}
function bindUi(){const upload=$('plan-files'),drop=$('drop-zone');upload.onchange=()=>setFiles(upload.files);for(const event of ['dragenter','dragover'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.add('dragging');});for(const event of ['dragleave','drop'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.remove('dragging');});drop.addEventListener('drop',e=>setFiles(e.dataTransfer.files));$('generate').onclick=recognize;$('blank-project').onclick=startBlank;$('import-json').onclick=()=>$('json-file').click();$('json-file').onchange=async e=>{try{const text=await e.target.files[0].text();openProject(JSON.parse(text));}catch(error){toast(error.message);}};
  $('back-start').onclick=()=>{if(state.walk)exitWalk();$('editor-screen').hidden=true;$('start-screen').hidden=false;};$('export-json').onclick=downloadProject;$('fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();$('plan-view').onclick=()=>{showPlan(state.floor);$('plan-dialog').showModal();};$('close-plan').onclick=()=>$('plan-dialog').close();$('plan-dialog').onclick=e=>{if(e.target===$('plan-dialog'))$('plan-dialog').close();};
  $('add-room').onclick=addRoom;$('add-wall').onclick=addWall;$('add-furniture').onclick=addFurniture;document.querySelectorAll('[data-add-surface]').forEach(button=>button.onclick=()=>addSurface(button.dataset.addSurface));$('add-block').onclick=addBlock;$('undo-edit').onclick=undo;$('delete-selected').onclick=removeSelected;$('view-3d').onclick=()=>setView('3d');$('view-top').onclick=()=>setView('top');$('reset-camera').onclick=focusCamera;$('show-walls').onchange=e=>setDisplay('walls',e.target.checked);$('show-volumes').onchange=e=>setDisplay('volumes',e.target.checked);$('show-surfaces').onchange=e=>setDisplay('surfaces',e.target.checked);$('show-furniture').onchange=e=>setDisplay('furniture',e.target.checked);$('only-spaces').onclick=toggleOnlySpaces;$('level-mode').onclick=toggleLevelMode;$('show-labels').onchange=e=>{state.labels=e.target.checked;updateVisibility();};$('auto-rotate').onclick=e=>{controls.autoRotate=!controls.autoRotate;e.target.classList.toggle('active',controls.autoRotate);};
  $('wall-height').oninput=e=>{state.wallHeight=Number(e.target.value);updateSection();};$('section-slider').oninput=e=>{state.section=Number(e.target.value);updateSection();};document.querySelectorAll('[data-axis]').forEach(b=>b.onclick=()=>{state.sectionAxis=b.dataset.axis;document.querySelectorAll('[data-axis]').forEach(x=>x.classList.toggle('active',x===b));updateSection();});$('reverse-section').onclick=e=>{state.reversed=!state.reversed;e.target.classList.toggle('active',state.reversed);updateSection();};document.querySelectorAll('[data-palette]').forEach(b=>b.onclick=()=>setPalette(b.dataset.palette));$('light-slider').oninput=e=>{const t=Number(e.target.value)/100;sun.intensity=.5+4*t;ambient.intensity=.8+2*t;};
  $('enter-walk').onclick=enterWalk;$('exit-walk').onclick=exitWalk;document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>moveWalk(b.dataset.move));$('eye-slider').oninput=e=>{state.eye=Number(e.target.value);updateWalkCamera();};$('fov-slider').oninput=e=>{camera.fov=Number(e.target.value);updateWalkCamera();};$('yaw-slider').oninput=e=>{state.yaw=Number(e.target.value);updateWalkCamera();};$('pitch-slider').oninput=e=>{state.pitch=Number(e.target.value);updateWalkCamera();};
  window.addEventListener('keydown',e=>{const typing=e.target.matches?.('input,textarea,select');if(e.key==='Escape'&&state.walk){exitWalk();return;}if(state.walk&&!typing){const move={w:'forward',ArrowUp:'forward',s:'back',ArrowDown:'back',a:'left',ArrowLeft:'left',d:'right',ArrowRight:'right'}[e.key];if(move){e.preventDefault();moveWalk(move);return;}}if(typing)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo();}if((e.key==='Delete'||e.key==='Backspace')&&state.selection){e.preventDefault();removeSelected();}});
}

bindUi();checkAi();showContinue();
window.spatialEditor={getState:()=>({floor:state.floor,room:state.room,selection:state.selection,section:state.section,walk:state.walk,project:state.project}),openProject,createBlankProject,startBlank,setFloor,select,setView,enterWalk,exitWalk,undo,removeSelected};
